#pragma once

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <optional>
#include <stdexcept>

namespace downshift {
struct SpeedSample {
    double instantaneous = 0, smoothed = 0, average = 0, peak = 0, elapsed = 0;
};

class SpeedTracker final {
public:
    [[nodiscard]] std::optional<SpeedSample> sample(std::uint64_t bytes, double seconds, bool force = false) {
        if (!std::isfinite(seconds) || seconds < lastTime_ || bytes < lastBytes_)
            throw std::invalid_argument("Non-monotonic speed sample.");
        const auto interval = seconds - lastTime_;
        if (interval <= 0 || (!force && interval < 0.25)) return std::nullopt;
        const auto rate = static_cast<double>(bytes - lastBytes_) / interval;
        const auto alpha = 1 - std::exp(-interval / 2.0);
        smoothed_ = initialized_ ? smoothed_ + alpha * (rate - smoothed_) : rate;
        initialized_ = true;
        if (interval >= 0.25 && rate > 0) {
            peak_ = fullPositiveWindow_ ? std::max(peak_, rate) : rate;
            fullPositiveWindow_ = true;
        } else if (!fullPositiveWindow_) peak_ = std::max(peak_, rate);
        lastTime_ = seconds; lastBytes_ = bytes;
        return SpeedSample{rate, smoothed_, static_cast<double>(bytes) / seconds, peak_, seconds};
    }
    [[nodiscard]] double smoothed() const noexcept { return smoothed_; }
    [[nodiscard]] double peak() const noexcept { return peak_; }
private:
    double lastTime_ = 0, smoothed_ = 0, peak_ = 0;
    std::uint64_t lastBytes_ = 0;
    bool initialized_ = false;
    bool fullPositiveWindow_ = false;
};
} // namespace downshift

src/core/SegmentScheduler/SegmentSchedul.text:
#pragma once

#include <cstdint>
#include <optional>
#include <stdexcept>

namespace downshift {
struct ByteRange {
    std::uint64_t first;
    std::uint64_t last;
    [[nodiscard]] std::uint64_t size() const noexcept { return last - first + 1; }
};

// Lazy allocation bounds memory independently of file size; sizing affects only unassigned bytes.
// The engine assigns each range once; completed handles take the next range.
class SegmentScheduler final {
public:
    SegmentScheduler(std::uint64_t total, std::uint64_t chunk) : total_(total), chunk_(chunk) {
        if (chunk == 0) throw std::invalid_argument("Chunk size must be positive.");
    }
    void setChunkSize(std::uint64_t chunk) {
        if (chunk == 0) throw std::invalid_argument("Chunk size must be positive.");
        chunk_ = chunk;
    }
    [[nodiscard]] std::uint64_t remaining() const noexcept { return total_ - next_; }
    [[nodiscard]] std::optional<ByteRange> next() noexcept {
        if (next_ == total_) return std::nullopt;
        const auto count = (total_ - next_ < chunk_) ? total_ - next_ : chunk_;
        const ByteRange range{next_, next_ + count - 1};
        next_ += count;
        return range;
    }
private:
    std::uint64_t total_, chunk_, next_ = 0;
};
} // namespace downshift

